139		if !ok {
140			return Org{}, ErrNotFound
141		}
142		if err := f(&o); err != nil {
143			return Org{}, err
144		}
145		o.ID = id
146		if err := checkOrg(o); err != nil {
147			return Org{}, err
148		}
149		s.orgs[id] = o
150		return o, nil
151	}
