122	func (r *Response) JSON(t testing.TB, v any) {
123		t.Helper()
124		if err := json.Unmarshal(r.Body, v); err != nil {
125			t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
126		}
127	}
128	
129	// Map decodes the body as a JSON object.
130	func (r *Response) Map(t testing.TB) map[string]any {
131		t.Helper()
132		var m map[string]any
133		r.JSON(t, &m)
134		return m
135	}
136	
137	// String is the status and body, for failure messages.
138	func (r *Response) String() string { return fmt.Sprintf("%d %s", r.Code, bytes.TrimSpace(r.Body)) }
139	
140	// Do sends a request to the server with key as its API key ("" for none). A body that is a string or []byte is sent as it
141	// is; any other non-nil body is sent as JSON.
142	func (e *Env) Do(method, path, key string, body any) *Response {
143		e.T.Helper()
144		return e.DoWith(method, path, key, body, nil)
145	}
146	
147	// DoWith is Do with extra request headers.
148	func (e *Env) DoWith(method, path, key string, body any, header http.Header) *Response {
149		e.T.Helper()
150		var rd io.Reader
151		switch b := body.(type) {
152		case nil:
153		case string:
154			rd = strings.NewReader(b)
155		case []byte:
156			rd = bytes.NewReader(b)
157		default:
158			raw, err := json.Marshal(b)
159			if err != nil {
160				e.T.Fatal(err)
161			}
162			rd = bytes.NewReader(raw)
163		}
164		req := httptest.NewRequest(method, path, rd)
165		if key != "" {
166			req.Header.Set("Authorization", "Bearer "+key)
167		}
168		for k, vs := range header {
169			for _, v := range vs {
170				req.Header.Add(k, v)
171			}
172		}
173		rec := httptest.NewRecorder()
174		e.Server.ServeHTTP(rec, req)
175		return &Response{Code: rec.Code, Header: rec.Header(), Body: rec.Body.Bytes()}
176	}
177	
178	// MustDo is Do that fails the test unless the answer has the status want, and decodes the body into out (when not nil).
179	func (e *Env) MustDo(want int, method, path, key string, body, out any) *Response {
180		e.T.Helper()
181		r := e.Do(method, path, key, body)
182		if r.Code != want {
183			e.T.Fatalf("%s %s: want %d, got %s", method, path, want, r)
184		}
185		if out != nil {
186			r.JSON(e.T, out)
187		}
188		return r
189	}
190	
191	// CreateCustomer creates a customer of org through the API.
192	func (e *Env) CreateCustomer(org Org, name, email string) store.Customer {
193		e.T.Helper()
194		var c store.Customer
195		e.MustDo(http.StatusCreated, "POST", "/v1/customers", org.Key, map[string]string{"name": name, "email": email}, &c)
196		return c
197	}
198	
199	// CreatePlan creates a monthly licensed plan of org through the API, priced in major units ("12.50").
200	func (e *Env) CreatePlan(org Org, name, currency, price string) store.Plan {
201		e.T.Helper()
202		var p store.Plan
203		e.MustDo(http.StatusCreated, "POST", "/v1/plans", org.Key, map[string]any{"name": name, "currency": currency, "price": price, "interval": "month"}, &p)
204		return p
205	}
206	
207	// ---- fakes
208	
209	// FakeHTTP plays the organizations' webhook receivers: it records every request and answers 200, or what Respond returns
210	// when it is set (a status code, or an error for a request that never got an answer).
211	type FakeHTTP struct {
212		// Respond, when set, answers each request. Set it before requests are made, or between them.
213		Respond func(r Request) (int, error)
214	
215		mu       sync.Mutex
216		requests []Request
217	}
218	
219	// Request is a request a FakeHTTP received.
220	type Request struct {
221		Method string
222		URL    string
223		Header http.Header
224		Body   []byte
225	}
226	
227	// Do implements webhooks.Doer.
228	func (f *FakeHTTP) Do(req *http.Request) (*http.Response, error) {
229		var body []byte
230		if req.Body != nil {
231			body, _ = io.ReadAll(req.Body)
232			req.Body.Close()
233		}
234		r := Request{Method: req.Method, URL: req.URL.String(), Header: req.Header.Clone(), Body: body}
235		f.mu.Lock()
236		f.requests = append(f.requests, r)
237		respond := f.Respond
238		f.mu.Unlock()
239		status := http.StatusOK
240		if respond != nil {
241			var err error
242			if status, err = respond(r); err != nil {
243				return nil, err
244			}
245		}
246		return &http.Response{StatusCode: status, Status: http.StatusText(status), Header: http.Header{}, Body: io.NopCloser(strings.NewReader("")), Request: req}, nil
247	}
248	
249	// Requests returns the requests received so far, oldest first.
250	func (f *FakeHTTP) Requests() []Request {
251		f.mu.Lock()
252		defer f.mu.Unlock()
253		return append([]Request(nil), f.requests...)
254	}
255	
256	// FakeDNS answers host lookups from the addresses Set gave it. Other hosts do not resolve.
257	type FakeDNS struct {
258		mu    sync.Mutex
259		hosts map[string][]string
260	}
261	
262	// Set makes host resolve to ips (none: the host does not resolve).
263	func (d *FakeDNS) Set(host string, ips ...string) {
264		d.mu.Lock()
265		defer d.mu.Unlock()
266		if d.hosts == nil {
267			d.hosts = map[string][]string{}
268		}
269		d.hosts[strings.ToLower(host)] = ips
270	}
271	
272	// LookupIPAddr implements webhooks.Resolver.
273	func (d *FakeDNS) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
274		d.mu.Lock()
275		ips := d.hosts[strings.ToLower(host)]
276		d.mu.Unlock()
277		if len(ips) == 0 {
278			return nil, &net.DNSError{Err: "no such host", Name: host, IsNotFound: true}
279		}
280		out := make([]net.IPAddr, 0, len(ips))
281		for _, s := range ips {
282			ip := net.ParseIP(s)
283			if ip == nil {
284				return nil, fmt.Errorf("FakeDNS: %q is not an IP address", s)
285			}
286			out = append(out, net.IPAddr{IP: ip})
287		}
288		return out, nil
289	}
