// importProblem returns the first problem with a record of an import, or "" when the record can be created. seen holds
// the lower-case email addresses of the earlier records; this record's address is added to it.
func (s *Server) importProblem(orgID string, in store.CustomerInput, seen map[string]bool) string {
	email := strings.TrimSpace(in.Email)
	key := strings.ToLower(email)
	dup := seen[key]
	if store.ValidCustomerEmail(email) {
		seen[key] = true
	}
	_, taken := s.store.FindCustomerByEmail(orgID, email)
	pm := strings.TrimSpace(in.DefaultPaymentMethod)
	switch {
	case strings.TrimSpace(in.Name) == "":
		return "missing_name"
	case !store.ValidCustomerEmail(email):
		return "invalid_email"
	case pm != "" && !strings.HasPrefix(pm, "pm_"):
		return "invalid_payment_method"
	case taken:
		return "email_taken"
	case dup:
		return "duplicate_email"
	}
	return ""
}

